      "severity": "low",
      "description": "Schema has no user_version or migration path, making future active-development changes risky once users have existing databases."
    },
    {
      "file": "tests/test_ingest.py",
      "lines": "21-69",
      "severity": "medium",
      "description": "Ingest tests cover lifecycle rank basics but miss changed allocation fields and equal-rank terminal stale-update regressions."
    }
  ],
